package com.sobrenaturaldirector.model.history;
import java.util.*;
public final class HistorySummary { private final Map<String,Integer> intents,themes,providers; private final Map<String,Long> cooldowns; private final Set<String> claims; private final boolean recentMajorEvent; private final long timeSinceMajorEvent; public HistorySummary(Map<String,Integer> intents,Map<String,Integer> themes,Map<String,Integer> providers,Map<String,Long> cooldowns,Set<String> claims,boolean recentMajorEvent,long timeSinceMajorEvent){this.intents=map(intents);this.themes=map(themes);this.providers=map(providers);this.cooldowns=Collections.unmodifiableMap(new TreeMap<String,Long>(cooldowns==null?Collections.<String,Long>emptyMap():cooldowns));this.claims=Collections.unmodifiableSet(new TreeSet<String>(claims==null?Collections.<String>emptySet():claims));this.recentMajorEvent=recentMajorEvent;this.timeSinceMajorEvent=timeSinceMajorEvent;}private static Map<String,Integer>map(Map<String,Integer>x){return Collections.unmodifiableMap(new TreeMap<String,Integer>(x==null?Collections.<String,Integer>emptyMap():x));}public Map<String,Integer> getIntents(){return intents;}public Map<String,Integer> getThemes(){return themes;}public Map<String,Integer> getProviders(){return providers;}public Map<String,Long> getCooldowns(){return cooldowns;}public Set<String> getClaims(){return claims;}public boolean isRecentMajorEvent(){return recentMajorEvent;}public long getTimeSinceMajorEvent(){return timeSinceMajorEvent;} }
